"""Fixed candidates for H986; no outcome-dependent replacements."""
BANK={
'antonym':([('hot','cold'),('big','small'),('up','down'),('good','bad'),('young','old'),('light','dark'),('wet','dry'),('fast','slow'),('open','closed'),('happy','sad'),('long','short'),('rich','poor'),('hard','soft'),('early','late'),('clean','dirty'),('full','empty')],['The opposite of {x} is','An antonym of {x} is']),
'animal_young':([('dog','puppy'),('cat','kitten'),('cow','calf'),('horse','foal'),('sheep','lamb'),('goat','kid'),('pig','piglet'),('chicken','chick'),('duck','duckling'),('goose','gosling'),('deer','fawn'),('lion','cub'),('bear','cub'),('frog','tadpole'),('swan','cygnet'),('rabbit','kit')],['A baby {x} is called a','The young of a {x} is called a']),
'plural_form':([('cat','cats'),('dog','dogs'),('book','books'),('car','cars'),('child','children'),('man','men'),('woman','women'),('tooth','teeth'),('foot','feet'),('mouse','mice'),('goose','geese'),('person','people'),('box','boxes'),('city','cities'),('leaf','leaves'),('wolf','wolves')],['The plural of {x} is','Singular: {x}. Plural:']),
'country_language':([('France','French'),('Germany','German'),('Spain','Spanish'),('Italy','Italian'),('Japan','Japanese'),('China','Chinese'),('Russia','Russian'),('Portugal','Portuguese'),('Greece','Greek'),('Turkey','Turkish'),('Poland','Polish'),('Hungary','Hungarian'),('Finland','Finnish'),('Sweden','Swedish'),('Norway','Norwegian'),('Denmark','Danish')],['The main language spoken in {x} is','People in {x} primarily speak']),
'continent_recall':([('France','Europe'),('Japan','Asia'),('Germany','Europe'),('China','Asia'),('Egypt','Africa'),('Brazil','America'),('Kenya','Africa'),('India','Asia'),('Italy','Europe'),('Nigeria','Africa'),('Spain','Europe'),('Thailand','Asia'),('Peru','America'),('Ghana','Africa'),('Poland','Europe'),('Vietnam','Asia')],['{x} is located in the continent of','The continent containing {x} is']),
'profession_tool':([('carpenter','hammer'),('painter','brush'),('surgeon','scalpel'),('chef','knife'),('musician','instrument'),('photographer','camera'),('writer','pen'),('dentist','drill'),('farmer','tractor'),('fisherman','net'),('tailor','needle'),('lumberjack','axe'),('scientist','microscope'),('astronomer','telescope'),('barber','scissors'),('gardener','shovel')],['A common tool used by a {x} is a','A {x} often works with a']),
'month_successor':(list(zip(['January','February','March','April','May','June','July','August','September','October','November','December'],['February','March','April','May','June','July','August','September','October','November','December','January'])),['The month after {x} is','The month immediately following {x} is']),
'number_word':(list(zip([str(i) for i in range(1,17)],['one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen'])),['The number {x} written in English is','Write {x} as an English word:']),
'comparative_form':([('big','bigger'),('small','smaller'),('fast','faster'),('slow','slower'),('tall','taller'),('short','shorter'),('old','older'),('young','younger'),('good','better'),('bad','worse'),('high','higher'),('low','lower'),('long','longer'),('strong','stronger'),('weak','weaker'),('cold','colder')],['The comparative form of {x} is','Positive: {x}. Comparative:']),
'object_function':([('knife','cutting'),('pen','writing'),('chair','sitting'),('bed','sleeping'),('oven','baking'),('refrigerator','cooling'),('broom','sweeping'),('soap','washing'),('camera','photography'),('telephone','communication'),('umbrella','rain'),('clock','time'),('thermometer','temperature'),('ruler','length'),('scale','weight'),('compass','direction')],['A {x} is used for','The purpose of a {x} is'])}
def suite():
 rows=[]
 for f,(items,formats) in BANK.items():
  for fmt,template in zip(['A','B'],formats):
   for i in range(8):
    # Month cycle has only12 entries; explicit shared-vocabulary limitation.
    a,b=(items[i],items[(i+4)%12]) if f=='month_successor' else (items[2*i],items[2*i+1])
    rows.append(dict(id=f'{f}-{fmt}-{i}',family=f,format=fmt,source=i,split=('discovery' if i<4 else 'lexical') if fmt=='A' else ('structural' if i<4 else 'joint'),whole_task_holdout=f in ['continent_recall','object_function'],prompts=[template.format(x=x) for x,y in [a,b]],answers=[a[1],b[1]],intervention_variable='queried item under fixed relation'))
 return rows
